('fdc2ff2e-f4c3-40c0-acb3-2a3844a21906','MA','a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',6.3,91.9,153,3.8,'active'),
('79dcc030-7f7b-48e4-9fd6-a0ece5f3e8cf','MA','a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',9.4,93,314,4.8,'active'),
('693f5217-33e2-4125-a9e7-abe65811fde8','MA','a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Essaouira Cooking School SARL','Dar Essaouira Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',10,94.3,110,4.9,'active'),
('53f594e1-dcbb-4fca-b0ac-d83e04b2fa47','MA','a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',10.2,89.9,203,3.5,'active'),
