('97fcf513-6c4d-422f-966e-f280ba146b33','MA','a06060a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',2.9,91.4,270,4.5,'active'),
('1430f593-f4e0-4b35-bd06-0ad7a8d39ffa','MA','a06060a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Ouzoud Budget SARL','Riad Ouzoud Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',4.6,88.8,221,4.8,'active'),
('abcdc02d-cb5f-47fa-8c5e-3590d718d9d5','MA','a06060a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Ouzoud Boutique SARL','Dar Ouzoud Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',1.6,94.9,279,4.9,'active'),
('45c5e3be-6ada-43d9-bb7d-1760f22f02de','MA','a06060a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Ouzoud Royal SARL','Palais Ouzoud Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',3.3,97.4,314,3.8,'active'),
('e05e3328-387f-45ff-a9e6-4a9052d275c5','MA','a06060a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Ouzoud Tours SARL','Street Food Ouzoud Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',2.4,91.7,167,3.6,'active'),
