('1d2ac1de-8d71-4acc-b6f2-18f3c2ccaf02','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Ouarzazate Budget SARL','Riad Ouarzazate Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',2.4,94.2,46,4.6,'active'),
('95bc37bd-caf3-4516-987b-de8155f9fc9a','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Ouarzazate Boutique SARL','Dar Ouarzazate Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',6.6,92,166,3.7,'active'),
('314d840c-65e6-4996-92c7-10cd3e2b40ed','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Ouarzazate Royal SARL','Palais Ouarzazate Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',11,94,52,3.9,'active'),
('60c42f9f-b060-4f8d-8c99-2995d68dd52e','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Ouarzazate Tours SARL','Street Food Ouarzazate Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',11,89.5,253,3.7,'active')
