('1459b02d-27cd-4889-a0b7-7f793ca45c49','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Ouarzazate Family Kitchen SARL','Table Ouarzazate Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',9.6,94.7,418,4.6,'active'),
('b92b9580-2238-4e70-b866-924779cff1a3','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Ouarzazate SARL','Le Salon Ouarzazate','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',4.7,96.5,415,5,'active'),
('50f30057-1faa-435c-9400-1d2bf7bc8937','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Desert Nomad Tours SARL','Desert Nomad Tours','desert_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'A Berber family business running camel treks and overnight camps in the dunes since 2005. Basic but authentic — real nomad-style camps with woven tents and campfire music.',9,93.5,61,4.4,'active'),
('ca57de04-ff5e-4165-8b4d-7892d86cb785','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Erg Luxury Expeditions SARL','Erg Luxury Expeditions','desert_experience',4,'verified',ARRAY['en','fr','es','it'],'Premium desert experiences with luxury glamping tents (real beds, en-suite bathrooms), gourmet dinners, and 4x4 Land Cruisers. Stargazing with a telescope included.',6.1,93.5,373,4.9,'active'),
('fba259cc-d479-47ae-9ef4-137be618e9af','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dune Riders Ouarzazate SARL','Dune Riders Ouarzazate','desert_experience',2,'verified',ARRAY['en','fr'],'A young team of desert enthusiasts offering sandboarding, quad biking, and buggy tours. Half-day and full-day options. Includes picnic lunch and water.',6.1,96.2,268,4.5,'active'),
('e0805475-1457-4765-995e-2b3f91260665','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Ouarzazate Shuttle Express SARL','Ouarzazate Shuttle Express','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers.',8.9,89.8,411,4.4,'active'),
('c17e4e8e-4a0c-4c28-b24b-49f5756e0583','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers SARL','Atlas Private Transfers','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability.',4.3,93,208,3.5,'active'),
('6fe87831-4a31-47a6-8f78-d896e5ec33f7','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',3.8,98,70,5,'active'),
('52c515f9-2923-4676-8d5b-1c1ef1983574','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','ONCF — Office National des Chemins de Fer SARL','ONCF — Office National des Chemins de Fer','transfer',2,'verified',ARRAY['en','fr','ar'],'Morocco''s national railway operator. High-speed Al Boraq trains connect Tangier to Casablanca via Rabat in under 3 hours. Conventional trains serve Casablanca, Rabat, Fès, Meknès, Marrakech, Tangier, and Oujda. Book at gare.oncf.ma or at any train station.',2,98,3393,4.1,'active'),
('5739712a-0461-4a9d-9307-5aec44a2d48f','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Ouarzazate Shuttle Express — Station Pickup SARL','Ouarzazate Shuttle Express — Station Pickup','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers. We also offer ONCF station pickup and drop-off services.',1.5,94,23,4.1,'active'),
('e566ec46-034c-42ae-933a-02aac4c472d3','MA','a00d00d0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers — Station Pickup SARL','Atlas Private Transfers — Station Pickup','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability. We also offer ONCF station pickup and drop-off services.',1.5,94,82,4.2,'active'),
