('846036f0-0ff7-4053-9bd0-4ee7263efe49','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Asilah Tours SARL','Street Food Asilah Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',2.1,97.8,29,3.8,'active'),
('a35b7f5e-d97b-48bd-8438-d5d75651e952','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Asilah Family Kitchen SARL','Table Asilah Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',10,96.4,376,4.8,'active'),
('37f360c4-63c3-4589-a31c-6a08b442c131','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Asilah SARL','Le Salon Asilah','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',5,98.2,295,4.1,'active'),
('c302f677-4d6a-4974-b287-acd3ac30bb1d','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Asilah Adventure Club SARL','Asilah Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',11.4,93.2,383,3.7,'active'),
('e8cc5ecd-4c65-4cfa-985e-6b701b20a5b1','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Extreme Sports SARL','Atlas Extreme Sports','activity',3,'verified',ARRAY['en','fr','de'],'Adrenaline specialists — quad biking, sandboarding, paragliding, and canyoning. Professional instructors, top safety record, and GoPro footage included.',6.7,91.4,377,3.7,'active'),
('189ca2b7-3657-41a7-9293-36a912a84005','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Sahara Wellness Retreat SARL','Sahara Wellness Retreat','activity',3,'verified',ARRAY['en','fr'],'A wellness sanctuary offering hammam, massage, yoga, and meditation sessions. Organic argan oil treatments and sound healing in a tranquil garden setting.',9,96.1,92,5,'active'),
('4768dbb6-501a-45ac-9780-59295e9c7844','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Asilah Shuttle Express SARL','Asilah Shuttle Express','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers.',4.9,94.4,127,4.1,'active'),
