('7d51cefa-2e4d-4f52-9fba-dd8b913c3899','MA','a09090a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Aït Ben Haddou Family Kitchen SARL','Table Aït Ben Haddou Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',4.3,95.8,125,4.8,'active'),
('f9465821-c0dc-4e2e-b78d-93e34491c82b','MA','a09090a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Aït Ben Haddou SARL','Le Salon Aït Ben Haddou','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',7.7,89.7,173,4.9,'active'),
